# ruff: noqa: E501
import base64
import io

import numpy as np
import pytest
from PIL import Image, ImageFile

from cms_backend.utils.image import images_differ

RNG = np.random.default_rng(0)

# https://stackoverflow.com/questions/42462431/oserror-broken-data-stream-when-reading-image-file#47958486
ImageFile.LOAD_TRUNCATED_IMAGES = True


def _opaque_indices(rgba: np.ndarray, n: int) -> tuple[np.ndarray, np.ndarray]:
    ys, xs = np.nonzero(rgba[..., 3] > 0)
    idx = RNG.choice(len(xs), size=n, replace=False)
    return ys[idx], xs[idx]


def _image_to_base64(image: Image.Image, _format: str = "PNG"):
    """Convert PIL Image to base64 string"""
    buffer = io.BytesIO()
    image.save(buffer, format=_format)
    buffer.seek(0)
    return base64.b64encode(buffer.getvalue()).decode()


def _variations(rgba: np.ndarray, image: Image.Image) -> dict[str, str]:
    """Build the named variations for a single illustration."""
    out: dict[str, str] = {}

    # 1. Slightly different colour, several pixels changed
    arr = rgba.copy()
    ys, xs = _opaque_indices(arr, n=12)
    arr[ys, xs, 0] = np.clip(arr[ys, xs, 0].astype(np.int16) + 5, 0, 255).astype(
        np.uint8
    )
    out["slight_multi_d5"] = _image_to_base64(Image.fromarray(arr, "RGBA"), "PNG")

    # 2. Same idea but with delta 15.
    arr = rgba.copy()
    ys, xs = _opaque_indices(arr, n=12)
    arr[ys, xs, 0] = np.clip(arr[ys, xs, 0].astype(np.int16) + 15, 0, 255).astype(
        np.uint8
    )
    out["slight_multi_d15"] = _image_to_base64(Image.fromarray(arr, "RGBA"), "PNG")

    # 3/4. Very different colour, only one / two pixels changed.
    for n, name in ((1, "strong_one_px"), (2, "strong_two_px")):
        arr = rgba.copy()
        ys, xs = _opaque_indices(arr, n=n)
        arr[ys, xs, :3] = 255 - arr[ys, xs, :3]
        out[name] = _image_to_base64(Image.fromarray(arr, "RGBA"), "PNG")

    # 5. Move the logo a couple of pixels (wrap-around shift).
    arr = np.roll(rgba, shift=(2, 2), axis=(0, 1))
    out["shift_2px"] = _image_to_base64(Image.fromarray(arr, "RGBA"), "PNG")

    # 6. Global brightness shift (small, applied to every opaque pixel).
    arr = rgba.copy()
    opaque = arr[..., 3] > 0
    arr[opaque, :3] = np.clip(arr[opaque, :3].astype(np.int16) + 3, 0, 255).astype(
        np.uint8
    )
    out["brightness_d3"] = _image_to_base64(Image.fromarray(arr, "RGBA"), "PNG")

    # 7. Alpha-only change: the RGB bytes are untouched.
    arr = rgba.copy()
    ys, xs = _opaque_indices(arr, n=20)
    arr[ys, xs, 3] = 0
    out["alpha_only_20px"] = _image_to_base64(Image.fromarray(arr, "RGBA"), "PNG")

    # 8. JPEG re-encode (lossy recompression). Alpha is dropped first.
    buf = io.BytesIO()
    image.convert("RGB").save(buf, format="JPEG", quality=85)
    buf.seek(0)
    out["jpeg_q85"] = _image_to_base64(Image.open(buf), "JPEG")

    # 9. Resize round-trip (downscale then upscale).
    resized = image.resize((46, 46), Image.Resampling.BILINEAR).resize(
        (48, 48), Image.Resampling.BILINEAR
    )
    out["resize_roundtrip"] = _image_to_base64(resized, "PNG")

    return out


def test_image_differs_ignores_slight_variations():
    illustration = ""

    raw = base64.b64decode(illustration)
    image = Image.open(io.BytesIO(raw))
    rgba = np.array(image)

    for _, variation in _variations(rgba, image).items():
        assert images_differ(variation, illustration)[0] is True


# Test the image differs algorithms against images incorrectly flagged by naive equality checking
# https://github.com/openzim/cms/issues/320#issuecomment-5660822174
@pytest.mark.parametrize(
    "book_illustration,title_illustration",
    [
        pytest.param(
            "",
            "",
            id="wikipedia_lzh_all",
        ),
        pytest.param(
            "",
            "",
            id="wikivoyage_en_europe-app",
        ),
        pytest.param(
            "",
            "",
            id="wikipedia_zh_chemistry",
        ),
        pytest.param(
            "",
            "",
            id="wikipedia_zh_geography",
        ),
        pytest.param(
            "",
            "",
            id="wikipedia_zh_physics",
        ),
        # https://github.com/openzim/cms/issues/557
        pytest.param(
            "",
            "",
        ),
        pytest.param(
            "",
            "",
        ),
        pytest.param(
            "",
            "",
        ),
    ],
)
def test_images_differ_different_base64_strings_same_image(
    book_illustration: str, title_illustration: str
):
    assert book_illustration != title_illustration
    assert images_differ(book_illustration, title_illustration)[0] is False


# https://github.com/openzim/cms/issues/534
@pytest.mark.parametrize(
    "book_illustration,title_illustration",
    [
        pytest.param(
            "",
            "",
            id="wikisource_la_all",
        )
    ],
)
def test_images_differ_different_shapes(
    book_illustration: str, title_illustration: str
):
    assert book_illustration != title_illustration
    differs, change_fraction = images_differ(book_illustration, title_illustration)
    assert differs is True
    assert change_fraction == 1.0
